from dataclasses import dataclass


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Calculate the area of a shape, rounded down."""
    match s:
        case Rect(w, h):
            return w * h
        case Square(side):
            return side * side
        case Tri(b, h):
            return (b * h) // 2


def test_area_rect() -> None:
    assert area(Rect(3, 4)) == 12
    assert area(Rect(0, 5)) == 0


def test_area_square() -> None:
    assert area(Square(5)) == 25
    assert area(Square(0)) == 0


def test_area_tri() -> None:
    assert area(Tri(4, 5)) == 10
    assert area(Tri(3, 3)) == 4
    assert area(Tri(1, 1)) == 0

